// Choose whether to pass a device path or NULL (NULL initializes only the DM backend)
unsigned int choice = *FUZZ_PARAM(unsigned int);
const char *maybe_path = (choice % 2) ? FUZZ_PARAM_FILENAME() : (const char *)NULL;
struct crypt_device *cd = NULL;
int rc = crypt_init(&cd, maybe_path);
// Must return 0 and set cd on success; otherwise bail to keep pool consistent
if (rc != 0 || !cd) { FUZZ_BAIL(); }
// Mark handle as initialized for downstream stubs
FUZZ_SET_ATTR_INT(cd, "initialized", 1);
// Track that the context type is not yet loaded/formatted
FUZZ_SET_ATTR_STR(cd, "type", "unknown");
// Output cd to the pool

// Prepare a header (metadata) device path and optionally a data device path
const char *header_path = FUZZ_PARAM_FILENAME();
unsigned int choice = *FUZZ_PARAM(unsigned int);
const char *data_path = (choice % 2) ? FUZZ_PARAM_FILENAME() : (const char *)NULL;
struct crypt_device *cd = NULL;
int rc = crypt_init_data_device(&cd, header_path, data_path);
if (rc != 0 || !cd) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(cd, "initialized", 1);
FUZZ_SET_ATTR_STR(cd, "type", "unknown");

// cd may be NULL or a valid initialized handle
crypt_free(cd);
// Do not return cd; runtime will drop it from the pool to avoid double free

// Require an initialized handle
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
// Pass NULL to accept all prompts automatically (we cannot define callbacks here)
crypt_set_confirm_callback(cd, (int(*)(const char*, void*))NULL, (void*)NULL);
// cd persists

if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
const char *path = FUZZ_PARAM_FILENAME();
(void)crypt_set_data_device(cd, path);
// cd persists regardless of success/failure

if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
// Enforce 4096-byte alignment as required
uint64_t mult = (uint64_t)(*FUZZ_PARAM(unsigned int) % 256);
uint64_t data_offset = mult * 4096ULL;
(void)crypt_set_data_offset(cd, data_offset);
// cd persists

// cd may be NULL to set default logger, but here we exercise per-handle
// Provide NULL to revert to default logging
crypt_set_log_callback(cd, (void(*)(int, const char*, void*))NULL, (void*)NULL);
// cd persists

// Emit a simple log line via default logger; cd may be NULL
int level = (int)(*FUZZ_PARAM(unsigned int) % 8); // library will clamp/interpret
std::string s = FUZZ_PARAM_STR();
crypt_log((struct crypt_device*)NULL, level, s.c_str());

// Formatted logging with default logger (cd == NULL)
int level = (int)(*FUZZ_PARAM(unsigned int) % 8);
std::string s = FUZZ_PARAM_STR();
int val = (int)(*FUZZ_PARAM(unsigned int));
crypt_logf((struct crypt_device*)NULL, level, "%s %d", s.c_str(), val);

if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
// Choose between two plausible RNG types; library validates values
int rng_type = (int)(*FUZZ_PARAM(unsigned int) % 2); // e.g., URANDOM(0) or RANDOM(1)
crypt_set_rng_type(cd, rng_type);
// cd persists

if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
(void)crypt_get_rng_type(cd);
// cd persists

if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
// Build a PBKDF configuration. Library validates type/hash and values.
static const char* types[3] = {"pbkdf2", "argon2i", "argon2id"};
static const char* hashes[3] = {"sha1", "sha256", "sha512"};
unsigned int t = *FUZZ_PARAM(unsigned int);
struct crypt_pbkdf_type pb = {0};
pb.type = types[t % 3];
pb.hash = hashes[(t/3) % 3];
pb.time_ms = (uint32_t)(10 + (t % 1000));
pb.iterations = (uint32_t)((t % 2) ? 0 : (1000 + (t % 5000))); // 0 means benchmark
pb.max_memory_kb = (uint32_t)(1024 + (t % 32768));
pb.parallel_threads = (uint32_t)(1 + (t % 8));
pb.flags = 0;
(void)crypt_set_pbkdf_type(cd, &pb);
// cd persists

// Query parameters for a named PBKDF; unknown names return NULL
static const char* names[4] = {"pbkdf2", "argon2i", "argon2id", "nonsense"};
const char *name = names[*FUZZ_PARAM(unsigned int) % 4];
(void)crypt_get_pbkdf_type_params(name);

// Query defaults for a device type; use common strings, allow unknown too
static const char* types[4] = {"LUKS1", "LUKS2", "luks1", "unknown"};
const char *type = types[*FUZZ_PARAM(unsigned int) % 4];
(void)crypt_get_pbkdf_default(type);

if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
(void)crypt_get_pbkdf_type(cd);
// cd persists

if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
uint64_t ms = (uint64_t)(*FUZZ_PARAM(unsigned int) % 5000);
crypt_set_iteration_time(cd, ms);
// cd persists

// This is a global switch; once disabled it cannot be enabled again in this process.
// Respect global state to avoid futile enable attempts.
int already_disabled = FUZZ_GET_ATTR_INT_GLOBAL("meta_lock_disabled");
int want_enable = (int)(*FUZZ_PARAM(unsigned int) & 1);
int effective_enable = already_disabled ? 0 : want_enable;
int rc = crypt_metadata_locking(cd, effective_enable);
if (rc == 0 && effective_enable == 0) {
    FUZZ_SET_ATTR_INT_GLOBAL("meta_lock_disabled", 1);
}
// cd persists

// Enforce initialized handle
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
// metadata_size must be one of the allowed kB values
static const uint64_t allowed_kb[9] = {16,32,64,128,256,512,1024,2048,4096};
unsigned int r = *FUZZ_PARAM(unsigned int);
uint64_t metadata_size = allowed_kb[r % 9] * 1024ULL; // bytes total (per API doc values are kB totals)
// keyslots_size must be a multiple of 4096 and <= 128MB
uint64_t blocks = (uint64_t)(1 + (r % 256)); // keep modest
uint64_t keyslots_size = blocks * 4096ULL;
if (keyslots_size > (128ULL * 1024ULL * 1024ULL)) keyslots_size = 128ULL * 1024ULL * 1024ULL;
(void)crypt_set_metadata_size(cd, metadata_size, keyslots_size);
// cd persists

// Retrieve sizes into stack outputs; handle must be initialized
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
uint64_t ms = 0, ks = 0;
(void)crypt_get_metadata_size(cd, &ms, &ks);
// cd persists

// Query device type; keep attribute in sync when known
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
const char *t = crypt_get_type(cd);
if (t) { FUZZ_SET_ATTR_STR(cd, "type", t); }
// cd persists

// Query HW encryption type; handle must be initialized
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
(void)crypt_get_hw_encryption_type(cd);
// cd persists

// Query HW encryption key size; handle must be initialized
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
(void)crypt_get_hw_encryption_key_size(cd);
// cd persists

// Requires initialized, not yet formatted context
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
const char *cur_type = FUZZ_GET_ATTR_STR(cd, "type");
int is_unknown = (cur_type && cur_type[0] != '\0' && !strcmp(cur_type, "unknown"));
if (!is_unknown) { FUZZ_BAIL(); }
// Prepare params
unsigned int r = *FUZZ_PARAM(unsigned int);
const char *cipher = (r & 1) ? "aes" : (const char*)NULL; // allow HW-only when NULL
const char *cipher_mode = cipher ? "xts-plain64" : (const char*)NULL;
const char *uuid = NULL;
const char *volume_keys = NULL; size_t volume_keys_size = 0; // SW encryption only
struct crypt_params_luks2 luks2 = {0};
struct crypt_params_hw_opal op = {0};
struct crypt_pbkdf_type pb = {0};
// Minimal LUKS2 params (PBKDF optional)
pb.type = "argon2id"; pb.hash = "sha256"; pb.time_ms = 100; pb.iterations = 0; pb.max_memory_kb = 4096; pb.parallel_threads = 1; pb.flags = 0;
luks2.pbkdf = &pb; luks2.integrity = NULL; luks2.integrity_params = NULL;
luks2.data_alignment = 0; luks2.data_device = NULL; luks2.sector_size = 0; luks2.label = NULL; luks2.subsystem = NULL;
// OPAL params
std::string ak = FUZZ_PARAM_STR(); op.admin_key = ak.data(); op.admin_key_size = (ak.size() > 64 ? 64 : ak.size());
op.user_key_size = (size_t)(16 + (r % 32));
// For SW encryption path provide volume_keys sometimes
if (cipher) {
    static const size_t vk_sizes[3] = {32, 64, 48};
    volume_keys_size = vk_sizes[r % 3];
    std::string vk = FUZZ_PARAM_STR();
    if (vk.size() >= volume_keys_size) volume_keys = vk.data();
}
int rc = crypt_format_luks2_opal(cd, cipher, cipher_mode, uuid, volume_keys, volume_keys_size, &luks2, &op);
if (rc == 0) {
    FUZZ_SET_ATTR_STR(cd, "type", "LUKS2");
    FUZZ_SET_ATTR_INT(cd, "is_luks", 1);
    FUZZ_SET_ATTR_INT(cd, "opal", 1);
}
// cd persists

// Inline integrity formatting requires initialized, not yet formatted context
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
const char *cur_type = FUZZ_GET_ATTR_STR(cd, "type");
int is_unknown = (cur_type && cur_type[0] != '\0' && !strcmp(cur_type, "unknown"));
if (!is_unknown) { FUZZ_BAIL(); }
// Choose type: INTEGRITY or LUKS2 with integrity
unsigned int r = *FUZZ_PARAM(unsigned int);
int choose_integrity = (r & 1);
const char *type = choose_integrity ? "INTEGRITY" : "LUKS2";
const char *uuid = NULL;
const char *cipher = choose_integrity ? (const char*)NULL : "aes"; // may be NULL for INTEGRITY
const char *cipher_mode = choose_integrity ? (const char*)NULL : "xts-plain64";
const char *volume_key = NULL; size_t volume_key_size = 0;
void *params = NULL;
struct crypt_params_integrity ip = {0};
struct crypt_params_luks2 l2 = {0};
struct crypt_pbkdf_type pb = {0};
// Prepare integrity params: journal-related fields must be zero; set minimal required fields
ip.journal_size = 0; ip.journal_watermark = 0; ip.journal_commit_time = 0; ip.interleave_sectors = 0;
ip.tag_size = 16; ip.sector_size = 4096; ip.buffer_sectors = 128; ip.integrity = "aead"; ip.integrity_key_size = 0;
ip.journal_integrity = NULL; ip.journal_integrity_key = NULL; ip.journal_integrity_key_size = 0;
ip.journal_crypt = NULL; ip.journal_crypt_key = NULL; ip.journal_crypt_key_size = 0;
if (choose_integrity) {
    params = &ip;
} else {
    pb.type = "argon2id"; pb.hash = "sha256"; pb.time_ms = 100; pb.iterations = 0; pb.max_memory_kb = 4096; pb.parallel_threads = 1; pb.flags = 0;
    l2.pbkdf = &pb; l2.integrity = "aead"; l2.integrity_params = &ip; l2.data_alignment = 0; l2.data_device = NULL; l2.sector_size = 4096; l2.label = NULL; l2.subsystem = NULL;
    // Optional VK
    static const size_t vk_sizes[2] = {32, 64};
    volume_key_size = vk_sizes[r % 2]; std::string vk = FUZZ_PARAM_STR();
    if (vk.size() >= volume_key_size) volume_key = vk.data(); else { volume_key = NULL; volume_key_size = 0; }
    params = &l2;
}
int rc = crypt_format_inline(cd, type, cipher, cipher_mode, uuid, volume_key, volume_key_size, params);
if (rc == 0) {
    FUZZ_SET_ATTR_STR(cd, "type", type);
    if (!strcmp(type, "LUKS2")) FUZZ_SET_ATTR_INT(cd, "is_luks", 1);
}
// cd persists

// Set some compatibility flags; handle must be initialized
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
uint32_t flags = (uint32_t)(*FUZZ_PARAM(unsigned int));
crypt_set_compatibility(cd, flags);
// cd persists

// Get compatibility flags; handle must be initialized
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
(void)crypt_get_compatibility(cd);
// cd persists

// Convert between LUKS1 and LUKS2; handle must be initialized
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
const char *cur = FUZZ_GET_ATTR_STR(cd, "type");
const char *target = (cur && !strcmp(cur, "LUKS1")) ? "LUKS2" : "LUKS1";
// No params are needed for LUKS conversions (API currently uses NULL)
(void)crypt_convert(cd, target, (void*)NULL);
// cd persists

// Set UUID requires a LUKS device; enforce initialized and LUKS context to keep API usage valid
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(cd, "is_luks")) { FUZZ_BAIL(); }
const char *uuid = ( (*FUZZ_PARAM(unsigned int)) & 1 ) ? (const char*)NULL : FUZZ_PARAM_STR().c_str();
(void)crypt_set_uuid(cd, uuid);
// cd persists

// LUKS2-only; enforce initialized and LUKS2 when known
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
const char *t = FUZZ_GET_ATTR_STR(cd, "type");
if (!(t && !strcmp(t, "LUKS2"))) { FUZZ_BAIL(); }
const char *label = ( (*FUZZ_PARAM(unsigned int)) & 1 ) ? FUZZ_PARAM_STR().c_str() : (const char*)NULL;
const char *subsystem = ( (*FUZZ_PARAM(unsigned int)) & 1 ) ? FUZZ_PARAM_STR().c_str() : (const char*)NULL;
(void)crypt_set_label(cd, label, subsystem);
// cd persists

// Get label; handle must be initialized; may return NULL
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
(void)crypt_get_label(cd);
// cd persists

// Get subsystem; handle must be initialized; may return NULL
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
(void)crypt_get_subsystem(cd);
// cd persists

// Global setting; cd may be NULL; enable/disable randomly
int enable = (int)(*FUZZ_PARAM(unsigned int) & 1);
(void)crypt_volume_key_keyring((struct crypt_device*)NULL, enable);

// Load on-disk metadata; requires initialized handle
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
// Randomly select requested_type and pass matching params or NULL for autodetect
unsigned int r = *FUZZ_PARAM(unsigned int);
static const char* reqs[5] = {NULL, "LUKS1", "LUKS2", "PLAIN", "VERITY"};
const char *requested = reqs[r % 5];
void *params = NULL;
struct crypt_params_luks1 p_l1 = {0};
struct crypt_params_luks2 p_l2 = {0};
struct crypt_params_plain p_pl = {0};
struct crypt_params_verity p_v = {0};
struct crypt_pbkdf_type pb = {0};
if (requested == NULL) {
    params = NULL;
} else if (!strcmp(requested, "LUKS1")) {
    p_l1.hash = "sha256"; p_l1.data_alignment = 0; p_l1.data_device = (const char*)NULL; params = &p_l1;
} else if (!strcmp(requested, "LUKS2")) {
    pb.type = "argon2id"; pb.hash = "sha256"; pb.time_ms = 100; pb.iterations = 0; pb.max_memory_kb = 4096; pb.parallel_threads = 1; pb.flags = 0;
    p_l2.pbkdf = &pb; p_l2.integrity = NULL; p_l2.integrity_params = NULL; p_l2.data_alignment = 0; p_l2.data_device = NULL; p_l2.sector_size = 0; p_l2.label = NULL; p_l2.subsystem = NULL; params = &p_l2;
} else if (!strcmp(requested, "PLAIN")) {
    p_pl.hash = NULL; p_pl.offset = 0; p_pl.skip = 0; p_pl.size = 0; p_pl.sector_size = 0; params = &p_pl;
} else { // VERITY
    p_v.hash_name = "sha256"; p_v.data_device = FUZZ_PARAM_FILENAME(); p_v.hash_device = NULL; p_v.fec_device = NULL; p_v.salt = NULL; p_v.salt_size = 0;
    p_v.hash_type = 0; p_v.data_block_size = 4096; p_v.hash_block_size = 4096; p_v.data_size = 0; p_v.hash_area_offset = 0; p_v.fec_area_offset = 0; p_v.fec_roots = 0; p_v.flags = 0; params = &p_v;
}
int rc = crypt_load(cd, requested, params);
if (rc == 0) {
    if (requested) { FUZZ_SET_ATTR_STR(cd, "type", requested); if (!strcmp(requested, "LUKS1") || !strcmp(requested, "LUKS2")) FUZZ_SET_ATTR_INT(cd, "is_luks", 1); }
}
// cd persists

// Attempt to repair header; requires initialized handle
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
unsigned int r = *FUZZ_PARAM(unsigned int);
static const char* reqs[3] = {NULL, "LUKS1", "LUKS2"};
const char *requested = reqs[r % 3];
void *params = NULL;
struct crypt_params_luks1 p_l1 = {0};
struct crypt_params_luks2 p_l2 = {0};
struct crypt_pbkdf_type pb = {0};
if (requested == NULL) {
    params = NULL;
} else if (!strcmp(requested, "LUKS1")) {
    p_l1.hash = "sha256"; p_l1.data_alignment = 0; p_l1.data_device = (const char*)NULL; params = &p_l1;
} else {
    pb.type = "argon2id"; pb.hash = "sha256"; pb.time_ms = 50; pb.iterations = 0; pb.max_memory_kb = 2048; pb.parallel_threads = 1; pb.flags = 0;
    p_l2.pbkdf = &pb; p_l2.integrity = NULL; p_l2.integrity_params = NULL; p_l2.data_alignment = 0; p_l2.data_device = NULL; p_l2.sector_size = 0; p_l2.label = NULL; p_l2.subsystem = NULL; params = &p_l2;
}
(void)crypt_repair(cd, requested, params);
// cd persists

// Resize may take NULL cd; provide a random name and size in sectors
std::string n = FUZZ_PARAM_STR();
uint64_t new_size = (uint64_t)(*FUZZ_PARAM(unsigned int));
(void)crypt_resize((struct crypt_device*)NULL, n.c_str(), new_size);
// No persistent objects involved

// cd may be NULL per API; we pass NULL and a random device-mapper name.
// This exercises error paths without requiring a real active mapping.
std::string name = FUZZ_PARAM_STR();
(void)crypt_suspend((struct crypt_device*)NULL, name.c_str());
// No persistent objects involved

// Requires initialized handle
if (!FUZZ_GET_ATTR_INT(cd, "initialized")) { FUZZ_BAIL(); }
