import random
import string
from typing import List

# Generator for a "passphrase string" bytes buffer.
# Produces valid, interesting passphrases covering various lengths and char classes.

WORD_LIST = [
    b"correct", b"horse", b"battery", b"staple", b"hunter2", b"letmein", b"passphrase",
    b"password", b"open sesame", b"libcryptsetup", b"argon2id", b"pbkdf2", b"sha256",
    b"LUKS2", b"verity", b"integrity", b"tcrypt", b"opal", b"keyslot", b"token",
]

SEP_LIST = [b" ", b"-", b"_", b"/", b"\t", b"::", b"|", b"."]

# Define symbol bytes safely without breaking Python string syntax
SYMBOLS = b"!@#$%^&*()[]{}<>=+?~,.:-_/\\|;\'\""

# Common UTF-8 snippets (ensure valid UTF-8 while still bytes)
UTF8_SNIPPETS = [
    "pässwörd".encode("utf-8"),
    "пароль".encode("utf-8"),
    "密碼".encode("utf-8"),
    "كلمةالسر".encode("utf-8"),
    "🔑🔒".encode("utf-8"),
    "密码🔐".encode("utf-8"),
]

PIN_PATTERNS = [
    b"0000", b"1234", b"0420", b"1337", b"314159", b"271828", b"8675309",
]

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _ascii_mixed(rng: random.Random, n: int) -> bytes:
    # Mix of letters, digits, symbols
    alphabet = (string.ascii_letters + string.digits).encode() + SYMBOLS
    return bytes(rng.choice(alphabet) for _ in range(n))


def _human_like(rng: random.Random, target_len: int) -> bytes:
    parts: List[bytes] = []
    length = 0
    while length < target_len:
        w = rng.choice(WORD_LIST)
        if rng.random() < 0.3:
            # Random casing
            w = rng.choice([w.lower(), w.upper(), w.title()])
        if parts:
            sep = rng.choice(SEP_LIST)
            parts.append(sep)
            length += len(sep)
        parts.append(w)
        length += len(w)
    out = b"".join(parts)
    if len(out) > target_len:
        out = out[:target_len]
    return out


def _utf8_rich(rng: random.Random, target_len: int) -> bytes:
    chunks: List[bytes] = []
    while sum(len(c) for c in chunks) < target_len:
        if rng.random() < 0.6:
            chunks.append(rng.choice(UTF8_SNIPPETS))
        else:
            chunks.append(_ascii_mixed(rng, rng.randint(1, 6)))
    out = b"".join(chunks)
    if len(out) > target_len:
        out = out[:target_len]
    return out


def _ensure_bounds(b: bytes, min_len: int, max_len: int) -> bytes:
    if len(b) < min_len:
        b = b + b"x" * (min_len - len(b))
    if len(b) > max_len:
        b = b[:max_len]
    return b


def _with_optional_newline(rng: random.Random, data: bytes) -> bytes:
    # Sometimes append newline to emulate keyfile lines; sometimes not.
    if rng.random() < 0.5:
        return data
    if len(data) < 4096 - 1:
        return data + b"\n"
    return data


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a scenario to exercise different code paths
    scenario = rng.choice([
        "empty", "short_ascii", "pin", "human_phrase", "utf8_rich",
        "long_ascii", "boundary_64", "boundary_65", "with_newline",
    ])

    if scenario == "empty":
        data = b""  # valid zero-length
    elif scenario == "short_ascii":
        data = _ascii_mixed(rng, rng.randint(1, 8))
    elif scenario == "pin":
        # Numeric-only PIN-like
        if rng.random() < 0.6:
            data = rng.choice(PIN_PATTERNS)
        else:
            n = rng.randint(4, 12)
            data = bytes(ord('0') + rng.randrange(10) for _ in range(n))
    elif scenario == "human_phrase":
        data = _human_like(rng, rng.randint(12, 40))
    elif scenario == "utf8_rich":
        data = _utf8_rich(rng, rng.randint(8, 48))
    elif scenario == "long_ascii":
        data = _ascii_mixed(rng, rng.randint(80, 256))
    elif scenario == "boundary_64":
        # Hit exactly 64 bytes
        data = _ascii_mixed(rng, 64)
    elif scenario == "boundary_65":
        # One over typical boundary
        data = _ascii_mixed(rng, 65)
    else:  # with_newline
        base = rng.choice([
            _human_like(rng, rng.randint(6, 20)),
            _ascii_mixed(rng, rng.randint(6, 20)),
            _utf8_rich(rng, rng.randint(6, 20)),
        ])
        data = _with_optional_newline(rng, base)

    # Occasionally prepend or append UTF-8 snippets to mix content
    if data and rng.random() < 0.25:
        if rng.random() < 0.5:
            data = rng.choice(UTF8_SNIPPETS) + b"-" + data
        else:
            data = data + b"-" + rng.choice(UTF8_SNIPPETS)

    # Enforce global size bounds
    data = _ensure_bounds(data, 0, 4096)

    return data
